using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD ERRORS ===");
build.VisitAllChildren<Error>(error => {
    Console.WriteLine($"[{error.ProjectFile}] {error.Code}: {error.Text}");
    Console.WriteLine($"  File: {error.File} Line: {error.LineNumber} Col: {error.ColumnNumber}");
    Console.WriteLine();
});

// Check if Api project has its own compilation errors or just dependency failures
Console.WriteLine("=== CHECKING CASCADING FAILURES ===");
build.VisitAllChildren<Target>(target => {
    if (target.Name == "ResolveProjectReferences" && !string.IsNullOrEmpty(target.Project?.ProjectFile)) {
        var projName = System.IO.Path.GetFileName(target.Project.ProjectFile);
        if (projName == "Api.csproj") {
            Console.WriteLine($"Api ResolveProjectReferences succeeded: {target.Succeeded}");
        }
    }
    if (target.Name == "CoreCompile" || target.Name == "Compile") {
        var projName = target.Project?.ProjectFile != null ? System.IO.Path.GetFileName(target.Project.ProjectFile) : "unknown";
        Console.WriteLine($"Target {target.Name} in {projName}: Succeeded={target.Succeeded}");
    }
});

Console.WriteLine($"\n=== BUILD SUCCEEDED: {build.Succeeded} ===");
EOF
